static void il2_6(double* restrict dst, const double* restrict src){
  for(long idx=0;idx<216;idx++){
    __m256d v = _mm256_castpd128_pd256(_mm_loadu_pd(src + idx*2));
    v = _mm256_insertf128_pd(v, _mm_loadu_pd(src + 432 + idx*2), 1);
    _mm256_store_pd(dst + idx*4, v);
  }
}
static void dl2_6(double* restrict dst, const double* restrict src){
  for(long idx=0;idx<216;idx++){
    __m256d v = _mm256_load_pd(src + idx*4);
    _mm_storeu_pd(dst + idx*2, _mm256_castpd256_pd128(v));
    _mm_storeu_pd(dst + 432 + idx*2, _mm256_extractf128_pd(v, 1));
  }
}


void run2_6(long G, long m, const double* restrict x0, const double* restrict c,
              double* restrict out1, double* restrict outm){
  for(long g=0;g<G;g++){
    il2_6(STATE, x0 + g*864);
    il2_6(CBUF, c + g*864);
    for(long s=0;s<m;s++){
      pass12_i2_6(STATE); pass3m_i2_6(STATE, CBUF);
      if(s==0) dl2_6(out1 + g*864, STATE);
    }
    dl2_6(outm + g*864, STATE);
  }
}

