void fft3_8(double* restrict x){
  pass12_8(x); pass3p_8(x, 0);
}
void step_8(double* restrict x, const double* restrict c){
  pass12_8(x); pass3m_8(x, c);
}
void run_8(long B, long m, double* restrict x0, const double* restrict c,
             double* restrict out1, double* restrict outm){
  for(long b=0;b<B;b++){
    double* restrict xb = x0 + b*1024;
    const double* restrict cb = c + b*1024;
    for(long s=0;s<m;s++){
      pass12_8(xb); pass3m_8(xb, cb);
      if(s==0) memcpy(out1 + b*1024, xb, 1024*sizeof(double));
    }
    memcpy(outm + b*1024, xb, 1024*sizeof(double));
  }
}

