static void il4_8(double* restrict dst, const double* restrict src){
  for(long idx=0;idx<512;idx++){
    __m512d v = _mm512_castpd128_pd512(_mm_loadu_pd(src + idx*2));
    v = _mm512_insertf64x2(v, _mm_loadu_pd(src + 1024 + idx*2), 1);
    v = _mm512_insertf64x2(v, _mm_loadu_pd(src + 2048 + idx*2), 2);
    v = _mm512_insertf64x2(v, _mm_loadu_pd(src + 3072 + idx*2), 3);
    _mm512_store_pd(dst + idx*8, v);
  }
}
static void dl4_8(double* restrict dst, const double* restrict src){
  for(long idx=0;idx<512;idx++){
    __m512d v = _mm512_load_pd(src + idx*8);
    _mm_storeu_pd(dst + idx*2, _mm512_castpd512_pd128(v));
    _mm_storeu_pd(dst + 1024 + idx*2, _mm512_extractf64x2_pd(v, 1));
    _mm_storeu_pd(dst + 2048 + idx*2, _mm512_extractf64x2_pd(v, 2));
    _mm_storeu_pd(dst + 3072 + idx*2, _mm512_extractf64x2_pd(v, 3));
  }
}


void run4_8(long G, long m, const double* restrict x0, const double* restrict c,
              double* restrict out1, double* restrict outm){
  for(long g=0;g<G;g++){
    il4_8(STATE, x0 + g*4096);
    il4_8(CBUF, c + g*4096);
    for(long s=0;s<m;s++){
      pass12_i4_8(STATE); pass3m_i4_8(STATE, CBUF);
      if(s==0) dl4_8(out1 + g*4096, STATE);
    }
    dl4_8(outm + g*4096, STATE);
  }
}

