void fft3_45(double* restrict x){
  pass12_45(x); pass3p_45(x, 0);
}
void step_45(double* restrict x, const double* restrict c){
  pass12_45(x); pass3m_45(x, c);
}
void run_45(long B, long m, double* restrict x0, const double* restrict c,
             double* restrict out1, double* restrict outm){
  for(long b=0;b<B;b++){
    memcpy(STATE, x0 + b*182250, 182250*sizeof(double));
    memcpy(CBUF, c + b*182250, 182250*sizeof(double));
    for(long s=0;s<m;s++){
      pass12_45(STATE); pass3m_45(STATE, CBUF);
      if(s==0) memcpy(out1 + b*182250, STATE, 182250*sizeof(double));
    }
    memcpy(outm + b*182250, STATE, 182250*sizeof(double));
  }
}

