void fft3_64(double* restrict x){
  pass12_64(x); pass3p_64(x, 0);
}
void step_64(double* restrict x, const double* restrict c){
  pass12_64(x); pass3m_64(x, c);
}
void run_64(long B, long m, double* restrict x0, const double* restrict c,
             double* restrict out1, double* restrict outm){
  for(long b=0;b<B;b++){
    memcpy(STATE, x0 + b*524288, 524288*sizeof(double));
    memcpy(CBUF, c + b*524288, 524288*sizeof(double));
    for(long s=0;s<m;s++){
      pass12_64(STATE); pass3m_64(STATE, CBUF);
      if(s==0) memcpy(out1 + b*524288, STATE, 524288*sizeof(double));
    }
    memcpy(outm + b*524288, STATE, 524288*sizeof(double));
  }
}
